window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-c9353920c306bf20"]={"versions": [{"id": "FIG-c9353920c306bf20", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Aktivitätsdiagramm (Activity Diagram) / Kontrollflussgraph mit Entscheidungsknoten (Decision Node) und Guard-Bedingungen.</li>\n<li><strong>Funktionale Einordnung:</strong> AUTOSAR Classic Platform (Release 4.2.2), BSW Communication Services Layer, Modul <code>SecOC</code> (Secure Onboard Communication).</li>\n<li><strong>Technischer Zweck:</strong> Spezifiziert den normativen Algorithmus zur Freshness-Wert-Synchronisation und Retry-Schleife während der Authentizitäts- und Integritätsprüfung einer empfangenen Secured I-PDU (Rx-Pfad) gemäß <strong>SWS_SecOC_00053</strong>. Werden zur Bandbreitenreduktion nur die Least Significant Bits (LSBs) des Freshness-Wertes über den Bus übertragen, ermöglicht diese Logik die Resynchronisation bei verpassten Botschaften/LSB-Überläufen durch schrittweises Inkrementieren der lokal rekonstruierten Most Significant Bits (MSBs).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure & Module:</strong></li>\n<li><code>SecOC</code>: Ausführende BSW-Entität.</li>\n<li><code>Crypto Service Manager (CSM)</code>: Unterlagerte Krypto-Schnittstelle zur Ausführung der Signatur-/MAC-Prüfung (<code>Csm_MacVerify</code> bzw. <code>Csm_SignatureVerify</code>).</li>\n<li><code>PduR</code> (PDU Router): Überlagerte Empfangsschicht (<code>PduR_SecOCRxIndication</code>).</li>\n<li><strong>Zustands- & Konfigurationsvariablen:</strong></li>\n<li><code>Attempts</code>: Lokale Laufzeitvariable (Schleifenzähler für Verifikationsiterationen, initial <code>0</code>).</li>\n<li><code>SecOCFreshnessValueSyncAttempts</code> (ECUC-Parameter): Maximal zulässige Anzahl an Re-Synchronisationsversuchen zur Rekonstruktion des vollständigen Freshness-Wertes.</li>\n<li><code>FreshnessVerifyValue</code>: Zusammengesetzter Verifikations-Vektor bestehend aus lokal gehaltenen MSBs und den in der Secured I-PDU übertragenen LSBs.</li>\n<li><strong>Kontrollfluss-Knoten & Konnektoren:</strong></li>\n<li>Initial Node: Eintritt über eingehende gesicherte PDU.</li>\n<li>Decision Node (Raute): Auswertung des Verifikationsergebnisses und der Guard-Bedingungen.</li>\n<li>Exit-Konnektoren:</li>\n<li><code>continue</code> (grün): Erfolgreicher Abschluss, Übergang zur Nutzdaten-Auslieferung.</li>\n<li><code>step back</code> (gelb): Rücksprung zur Wiederholung der Krypto-Prüfung.</li>\n<li><code>abort</code> (rot): Terminaler Fehlerzustand, Verwerfen der PDU.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> Aufruf von <code>SecOC_RxIndication()</code> durch die unterlagerte Schnittstelle (z. B. CanIf, FrIf, SoAd). <code>SecOC</code> baut den ersten Prüfvektor <code>FreshnessVerifyValue</code> auf.</li>\n<li><strong>MAC Verification:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ausführung der MAC-Verifikation über Nutzdaten (Authentic I-PDU) und <code>FreshnessVerifyValue</code> via CSM (synchron oder asynchron).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Verzweigung via Guard-Bedingungen:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Pfad 1 (<code>passes</code>):</strong></li>\n<li>MAC ist valide.</li>\n<li>Fluss terminiert auf Konnektor <code>continue</code>.</li>\n<li><code>SecOC</code> aktualisiert den lokalen Freshness-Wert (persistente MSBs) und leitet die Authentic I-PDU via <code>PduR_SecOCRxIndication()</code> an den PduR weiter.</li>\n<li><strong>Pfad 2 (<code>fails &amp;&amp; [Attempts &lt; SecOCFreshnessValueSyncAttempts]</code>):</strong></li>\n<li>MAC ist ungültig, das Synchronisationsfenster ist noch nicht ausgeschöpft.</li>\n<li>Aktion 1: <code>Attempts++</code> (Inkrementierung des Versuchszählers).</li>\n<li>Aktion 2: <code>most significant bits of FreshnessVerifyValue ++1</code> (Annahme: LSB-Überlauf fand auf Senderseite bereits statt, Empfänger verpasste mindestens ein Sendeintervall).</li>\n<li>Fluss terminiert auf Konnektor <code>step back</code>: Rücksprung zur erneuten Ausführung von <code>MAC Verification</code> mit dem modifizierten <code>FreshnessVerifyValue</code>.</li>\n<li><strong>Pfad 3 (<code>fails &amp;&amp; [Attempts &gt;= SecOCFreshnessValueSyncAttempts]</code>):</strong></li>\n<li>MAC ist ungültig und das Limit der Re-Synchronisationsversuche ist erreicht oder überschritten.</li>\n<li>Aktion: <code>Drop message</code> (PDU wird verworfen, keine Weiterleitung an PduR).</li>\n<li>Fluss geht auf <code>abort</code>: Fehlermeldung an <code>Dem</code> (z. B. <code>SECOC_E_VERIFICATION_FAILURE</code>) bzw. Sicherheits-Event-Logging via <code>IdsM</code>.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>WCET & Task-Scheduling-Einfluss:</strong></li>\n<li>Ist <code>SecOCFreshnessValueSyncAttempts</code> auf $N$ konfiguriert, resultiert dies im Worst Case in $(N + 1)$ sequentiellen CSM-Aufrufen für einen einzigen Rx-Frame.</li>\n<li>Bei synchroner CSM-Verarbeitung im Kontext der Kommunikations-Task (<code>SecOC_MainFunctionRx</code> oder Rx-ISR) führt dies zu massiven CPU-Lastspitzen und potenziellen Task-Overruns. Bei hohen Datenraten oder CAN-Bursts muss die asynchrone CSM-Anbindung mit PDU-Queuing implementiert werden.</li>\n<li><strong>Denial-of-Service (DoS) & Buslast-Exposition:</strong></li>\n<li>Ein Angreifer kann durch bewusst manipulierte MACs die Empfänger-ECU dazu zwingen, für jede injizierte PDU das maximale Synchronisationsfenster vollständig abzuarbeiten. Der Parameter <code>SecOCFreshnessValueSyncAttempts</code> ist daher so klein wie möglich zu wählen (typisch $1 \\dots 3$).</li>\n<li><strong>Zustandskonsistenz der Freshness-Quelle:</strong></li>\n<li>Das Inkrementieren der MSBs (<code>FreshnessVerifyValue ++1</code>) darf während der Iterationen ausschließlich auf einer <strong>lokalen Arbeitskopie</strong> für die Verifikation erfolgen. Eine Übernahme in den persistenten lokalen Freshness-Zustand des Empfängers darf erst und ausschließlich bei Traversierung des <code>continue</code>-Pfades erfolgen.</li>\n</ul>"}, {"id": "FIG-0d5a4627ecec958a", "releases": ["R4.3.1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Aktivitätsdiagramm (Activity Diagram) / Kontrollflussgraph mit Entscheidungsknoten (Decision Node) und Guard-Bedingungen.</li>\n<li><strong>Funktionale Einordnung:</strong> AUTOSAR Classic Platform (Release 4.2.2), BSW Communication Services Layer, Modul <code>SecOC</code> (Secure Onboard Communication).</li>\n<li><strong>Technischer Zweck:</strong> Spezifiziert den normativen Algorithmus zur Freshness-Wert-Synchronisation und Retry-Schleife während der Authentizitäts- und Integritätsprüfung einer empfangenen Secured I-PDU (Rx-Pfad) gemäß <strong>SWS_SecOC_00053</strong>. Werden zur Bandbreitenreduktion nur die Least Significant Bits (LSBs) des Freshness-Wertes über den Bus übertragen, ermöglicht diese Logik die Resynchronisation bei verpassten Botschaften/LSB-Überläufen durch schrittweises Inkrementieren der lokal rekonstruierten Most Significant Bits (MSBs).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure & Module:</strong></li>\n<li><code>SecOC</code>: Ausführende BSW-Entität.</li>\n<li><code>Crypto Service Manager (CSM)</code>: Unterlagerte Krypto-Schnittstelle zur Ausführung der Signatur-/MAC-Prüfung (<code>Csm_MacVerify</code> bzw. <code>Csm_SignatureVerify</code>).</li>\n<li><code>PduR</code> (PDU Router): Überlagerte Empfangsschicht (<code>PduR_SecOCRxIndication</code>).</li>\n<li><strong>Zustands- & Konfigurationsvariablen:</strong></li>\n<li><code>Attempts</code>: Lokale Laufzeitvariable (Schleifenzähler für Verifikationsiterationen, initial <code>0</code>).</li>\n<li><code>SecOCFreshnessValueSyncAttempts</code> (ECUC-Parameter): Maximal zulässige Anzahl an Re-Synchronisationsversuchen zur Rekonstruktion des vollständigen Freshness-Wertes.</li>\n<li><code>FreshnessVerifyValue</code>: Zusammengesetzter Verifikations-Vektor bestehend aus lokal gehaltenen MSBs und den in der Secured I-PDU übertragenen LSBs.</li>\n<li><strong>Kontrollfluss-Knoten & Konnektoren:</strong></li>\n<li>Initial Node: Eintritt über eingehende gesicherte PDU.</li>\n<li>Decision Node (Raute): Auswertung des Verifikationsergebnisses und der Guard-Bedingungen.</li>\n<li>Exit-Konnektoren:</li>\n<li><code>continue</code> (grün): Erfolgreicher Abschluss, Übergang zur Nutzdaten-Auslieferung.</li>\n<li><code>step back</code> (gelb): Rücksprung zur Wiederholung der Krypto-Prüfung.</li>\n<li><code>abort</code> (rot): Terminaler Fehlerzustand, Verwerfen der PDU.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> Aufruf von <code>SecOC_RxIndication()</code> durch die unterlagerte Schnittstelle (z. B. CanIf, FrIf, SoAd). <code>SecOC</code> baut den ersten Prüfvektor <code>FreshnessVerifyValue</code> auf.</li>\n<li><strong>MAC Verification:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ausführung der MAC-Verifikation über Nutzdaten (Authentic I-PDU) und <code>FreshnessVerifyValue</code> via CSM (synchron oder asynchron).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Verzweigung via Guard-Bedingungen:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Pfad 1 (<code>passes</code>):</strong></li>\n<li>MAC ist valide.</li>\n<li>Fluss terminiert auf Konnektor <code>continue</code>.</li>\n<li><code>SecOC</code> aktualisiert den lokalen Freshness-Wert (persistente MSBs) und leitet die Authentic I-PDU via <code>PduR_SecOCRxIndication()</code> an den PduR weiter.</li>\n<li><strong>Pfad 2 (<code>fails &amp;&amp; [Attempts &lt; SecOCFreshnessValueSyncAttempts]</code>):</strong></li>\n<li>MAC ist ungültig, das Synchronisationsfenster ist noch nicht ausgeschöpft.</li>\n<li>Aktion 1: <code>Attempts++</code> (Inkrementierung des Versuchszählers).</li>\n<li>Aktion 2: <code>most significant bits of FreshnessVerifyValue ++1</code> (Annahme: LSB-Überlauf fand auf Senderseite bereits statt, Empfänger verpasste mindestens ein Sendeintervall).</li>\n<li>Fluss terminiert auf Konnektor <code>step back</code>: Rücksprung zur erneuten Ausführung von <code>MAC Verification</code> mit dem modifizierten <code>FreshnessVerifyValue</code>.</li>\n<li><strong>Pfad 3 (<code>fails &amp;&amp; [Attempts &gt;= SecOCFreshnessValueSyncAttempts]</code>):</strong></li>\n<li>MAC ist ungültig und das Limit der Re-Synchronisationsversuche ist erreicht oder überschritten.</li>\n<li>Aktion: <code>Drop message</code> (PDU wird verworfen, keine Weiterleitung an PduR).</li>\n<li>Fluss geht auf <code>abort</code>: Fehlermeldung an <code>Dem</code> (z. B. <code>SECOC_E_VERIFICATION_FAILURE</code>) bzw. Sicherheits-Event-Logging via <code>IdsM</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>WCET & Task-Scheduling-Einfluss:</strong></li>\n<li>Ist <code>SecOCFreshnessValueSyncAttempts</code> auf $N$ konfiguriert, resultiert dies im Worst Case in $(N + 1)$ sequentiellen CSM-Aufrufen für einen einzigen Rx-Frame.</li>\n<li>Bei synchroner CSM-Verarbeitung im Kontext der Kommunikations-Task (<code>SecOC_MainFunctionRx</code> oder Rx-ISR) führt dies zu massiven CPU-Lastspitzen und potenziellen Task-Overruns. Bei hohen Datenraten oder CAN-Bursts muss die asynchrone CSM-Anbindung mit PDU-Queuing implementiert werden.</li>\n<li><strong>Denial-of-Service (DoS) & Buslast-Exposition:</strong></li>\n<li>Ein Angreifer kann durch bewusst manipulierte MACs die Empfänger-ECU dazu zwingen, für jede injizierte PDU das maximale Synchronisationsfenster vollständig abzuarbeiten. Der Parameter <code>SecOCFreshnessValueSyncAttempts</code> ist daher so klein wie möglich zu wählen (typisch $1 \\dots 3$).</li>\n<li><strong>Zustandskonsistenz der Freshness-Quelle:</strong></li>\n<li>Das Inkrementieren der MSBs (<code>FreshnessVerifyValue ++1</code>) darf während der Iterationen ausschließlich auf einer <strong>lokalen Arbeitskopie</strong> für die Verifikation erfolgen. Eine Übernahme in den persistenten lokalen Freshness-Zustand des Empfängers darf erst und ausschließlich bei Traversierung des <code>continue</code>-Pfades erfolgen.</li>\n</ul>"}, {"id": "FIG-117b8a2918abfa19", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Aktivitätsdiagramm (Activity Diagram) / Kontrollflussgraph mit Entscheidungsknoten (Decision Node) und Guard-Bedingungen.</li>\n<li><strong>Funktionale Einordnung:</strong> AUTOSAR Classic Platform (Release 4.2.2), BSW Communication Services Layer, Modul <code>SecOC</code> (Secure Onboard Communication).</li>\n<li><strong>Technischer Zweck:</strong> Spezifiziert den normativen Algorithmus zur Freshness-Wert-Synchronisation und Retry-Schleife während der Authentizitäts- und Integritätsprüfung einer empfangenen Secured I-PDU (Rx-Pfad) gemäß <strong>SWS_SecOC_00053</strong>. Werden zur Bandbreitenreduktion nur die Least Significant Bits (LSBs) des Freshness-Wertes über den Bus übertragen, ermöglicht diese Logik die Resynchronisation bei verpassten Botschaften/LSB-Überläufen durch schrittweises Inkrementieren der lokal rekonstruierten Most Significant Bits (MSBs).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure & Module:</strong></li>\n<li><code>SecOC</code>: Ausführende BSW-Entität.</li>\n<li><code>Crypto Service Manager (CSM)</code>: Unterlagerte Krypto-Schnittstelle zur Ausführung der Signatur-/MAC-Prüfung (<code>Csm_MacVerify</code> bzw. <code>Csm_SignatureVerify</code>).</li>\n<li><code>PduR</code> (PDU Router): Überlagerte Empfangsschicht (<code>PduR_SecOCRxIndication</code>).</li>\n<li><strong>Zustands- & Konfigurationsvariablen:</strong></li>\n<li><code>Attempts</code>: Lokale Laufzeitvariable (Schleifenzähler für Verifikationsiterationen, initial <code>0</code>).</li>\n<li><code>SecOCFreshnessValueSyncAttempts</code> (ECUC-Parameter): Maximal zulässige Anzahl an Re-Synchronisationsversuchen zur Rekonstruktion des vollständigen Freshness-Wertes.</li>\n<li><code>FreshnessVerifyValue</code>: Zusammengesetzter Verifikations-Vektor bestehend aus lokal gehaltenen MSBs und den in der Secured I-PDU übertragenen LSBs.</li>\n<li><strong>Kontrollfluss-Knoten & Konnektoren:</strong></li>\n<li>Initial Node: Eintritt über eingehende gesicherte PDU.</li>\n<li>Decision Node (Raute): Auswertung des Verifikationsergebnisses und der Guard-Bedingungen.</li>\n<li>Exit-Konnektoren:</li>\n<li><code>continue</code> (grün): Erfolgreicher Abschluss, Übergang zur Nutzdaten-Auslieferung.</li>\n<li><code>step back</code> (gelb): Rücksprung zur Wiederholung der Krypto-Prüfung.</li>\n<li><code>abort</code> (rot): Terminaler Fehlerzustand, Verwerfen der PDU.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> Aufruf von <code>SecOC_RxIndication()</code> durch die unterlagerte Schnittstelle (z. B. CanIf, FrIf, SoAd). <code>SecOC</code> baut den ersten Prüfvektor <code>FreshnessVerifyValue</code> auf.</li>\n<li><strong>MAC Verification:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ausführung der MAC-Verifikation über Nutzdaten (Authentic I-PDU) und <code>FreshnessVerifyValue</code> via CSM (synchron oder asynchron).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Verzweigung via Guard-Bedingungen:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Pfad 1 (<code>passes</code>):</strong></li>\n<li>MAC ist valide.</li>\n<li>Fluss terminiert auf Konnektor <code>continue</code>.</li>\n<li><code>SecOC</code> aktualisiert den lokalen Freshness-Wert (persistente MSBs) und leitet die Authentic I-PDU via <code>PduR_SecOCRxIndication()</code> an den PduR weiter.</li>\n<li><strong>Pfad 2 (<code>fails &amp;&amp; [Attempts &lt; SecOCFreshnessValueSyncAttempts]</code>):</strong></li>\n<li>MAC ist ungültig, das Synchronisationsfenster ist noch nicht ausgeschöpft.</li>\n<li>Aktion 1: <code>Attempts++</code> (Inkrementierung des Versuchszählers).</li>\n<li>Aktion 2: <code>most significant bits of FreshnessVerifyValue ++1</code> (Annahme: LSB-Überlauf fand auf Senderseite bereits statt, Empfänger verpasste mindestens ein Sendeintervall).</li>\n<li>Fluss terminiert auf Konnektor <code>step back</code>: Rücksprung zur erneuten Ausführung von <code>MAC Verification</code> mit dem modifizierten <code>FreshnessVerifyValue</code>.</li>\n<li><strong>Pfad 3 (<code>fails &amp;&amp; [Attempts &gt;= SecOCFreshnessValueSyncAttempts]</code>):</strong></li>\n<li>MAC ist ungültig und das Limit der Re-Synchronisationsversuche ist erreicht oder überschritten.</li>\n<li>Aktion: <code>Drop message</code> (PDU wird verworfen, keine Weiterleitung an PduR).</li>\n<li>Fluss geht auf <code>abort</code>: Fehlermeldung an <code>Dem</code> (z. B. <code>SECOC_E_VERIFICATION_FAILURE</code>) bzw. Sicherheits-Event-Logging via <code>IdsM</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>WCET & Task-Scheduling-Einfluss:</strong></li>\n<li>Ist <code>SecOCFreshnessValueSyncAttempts</code> auf $N$ konfiguriert, resultiert dies im Worst Case in $(N + 1)$ sequentiellen CSM-Aufrufen für einen einzigen Rx-Frame.</li>\n<li>Bei synchroner CSM-Verarbeitung im Kontext der Kommunikations-Task (<code>SecOC_MainFunctionRx</code> oder Rx-ISR) führt dies zu massiven CPU-Lastspitzen und potenziellen Task-Overruns. Bei hohen Datenraten oder CAN-Bursts muss die asynchrone CSM-Anbindung mit PDU-Queuing implementiert werden.</li>\n<li><strong>Denial-of-Service (DoS) & Buslast-Exposition:</strong></li>\n<li>Ein Angreifer kann durch bewusst manipulierte MACs die Empfänger-ECU dazu zwingen, für jede injizierte PDU das maximale Synchronisationsfenster vollständig abzuarbeiten. Der Parameter <code>SecOCFreshnessValueSyncAttempts</code> ist daher so klein wie möglich zu wählen (typisch $1 \\dots 3$).</li>\n<li><strong>Zustandskonsistenz der Freshness-Quelle:</strong></li>\n<li>Das Inkrementieren der MSBs (<code>FreshnessVerifyValue ++1</code>) darf während der Iterationen ausschließlich auf einer <strong>lokalen Arbeitskopie</strong> für die Verifikation erfolgen. Eine Übernahme in den persistenten lokalen Freshness-Zustand des Empfängers darf erst und ausschließlich bei Traversierung des <code>continue</code>-Pfades erfolgen.</li>\n</ul>"}, {"id": "FIG-23addafec55e3345", "releases": ["R20-11", "R21-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Aktivitätsdiagramm (Activity Diagram) / Kontrollflussgraph mit Entscheidungsknoten (Decision Node) und Guard-Bedingungen.</li>\n<li><strong>Funktionale Einordnung:</strong> AUTOSAR Classic Platform (Release 4.2.2), BSW Communication Services Layer, Modul <code>SecOC</code> (Secure Onboard Communication).</li>\n<li><strong>Technischer Zweck:</strong> Spezifiziert den normativen Algorithmus zur Freshness-Wert-Synchronisation und Retry-Schleife während der Authentizitäts- und Integritätsprüfung einer empfangenen Secured I-PDU (Rx-Pfad) gemäß <strong>SWS_SecOC_00053</strong>. Werden zur Bandbreitenreduktion nur die Least Significant Bits (LSBs) des Freshness-Wertes über den Bus übertragen, ermöglicht diese Logik die Resynchronisation bei verpassten Botschaften/LSB-Überläufen durch schrittweises Inkrementieren der lokal rekonstruierten Most Significant Bits (MSBs).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure & Module:</strong></li>\n<li><code>SecOC</code>: Ausführende BSW-Entität.</li>\n<li><code>Crypto Service Manager (CSM)</code>: Unterlagerte Krypto-Schnittstelle zur Ausführung der Signatur-/MAC-Prüfung (<code>Csm_MacVerify</code> bzw. <code>Csm_SignatureVerify</code>).</li>\n<li><code>PduR</code> (PDU Router): Überlagerte Empfangsschicht (<code>PduR_SecOCRxIndication</code>).</li>\n<li><strong>Zustands- & Konfigurationsvariablen:</strong></li>\n<li><code>Attempts</code>: Lokale Laufzeitvariable (Schleifenzähler für Verifikationsiterationen, initial <code>0</code>).</li>\n<li><code>SecOCFreshnessValueSyncAttempts</code> (ECUC-Parameter): Maximal zulässige Anzahl an Re-Synchronisationsversuchen zur Rekonstruktion des vollständigen Freshness-Wertes.</li>\n<li><code>FreshnessVerifyValue</code>: Zusammengesetzter Verifikations-Vektor bestehend aus lokal gehaltenen MSBs und den in der Secured I-PDU übertragenen LSBs.</li>\n<li><strong>Kontrollfluss-Knoten & Konnektoren:</strong></li>\n<li>Initial Node: Eintritt über eingehende gesicherte PDU.</li>\n<li>Decision Node (Raute): Auswertung des Verifikationsergebnisses und der Guard-Bedingungen.</li>\n<li>Exit-Konnektoren:</li>\n<li><code>continue</code> (grün): Erfolgreicher Abschluss, Übergang zur Nutzdaten-Auslieferung.</li>\n<li><code>step back</code> (gelb): Rücksprung zur Wiederholung der Krypto-Prüfung.</li>\n<li><code>abort</code> (rot): Terminaler Fehlerzustand, Verwerfen der PDU.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> Aufruf von <code>SecOC_RxIndication()</code> durch die unterlagerte Schnittstelle (z. B. CanIf, FrIf, SoAd). <code>SecOC</code> baut den ersten Prüfvektor <code>FreshnessVerifyValue</code> auf.</li>\n<li><strong>MAC Verification:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ausführung der MAC-Verifikation über Nutzdaten (Authentic I-PDU) und <code>FreshnessVerifyValue</code> via CSM (synchron oder asynchron).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Verzweigung via Guard-Bedingungen:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Pfad 1 (<code>passes</code>):</strong></li>\n<li>MAC ist valide.</li>\n<li>Fluss terminiert auf Konnektor <code>continue</code>.</li>\n<li><code>SecOC</code> aktualisiert den lokalen Freshness-Wert (persistente MSBs) und leitet die Authentic I-PDU via <code>PduR_SecOCRxIndication()</code> an den PduR weiter.</li>\n<li><strong>Pfad 2 (<code>fails &amp;&amp; [Attempts &lt; SecOCFreshnessValueSyncAttempts]</code>):</strong></li>\n<li>MAC ist ungültig, das Synchronisationsfenster ist noch nicht ausgeschöpft.</li>\n<li>Aktion 1: <code>Attempts++</code> (Inkrementierung des Versuchszählers).</li>\n<li>Aktion 2: <code>most significant bits of FreshnessVerifyValue ++1</code> (Annahme: LSB-Überlauf fand auf Senderseite bereits statt, Empfänger verpasste mindestens ein Sendeintervall).</li>\n<li>Fluss terminiert auf Konnektor <code>step back</code>: Rücksprung zur erneuten Ausführung von <code>MAC Verification</code> mit dem modifizierten <code>FreshnessVerifyValue</code>.</li>\n<li><strong>Pfad 3 (<code>fails &amp;&amp; [Attempts &gt;= SecOCFreshnessValueSyncAttempts]</code>):</strong></li>\n<li>MAC ist ungültig und das Limit der Re-Synchronisationsversuche ist erreicht oder überschritten.</li>\n<li>Aktion: <code>Drop message</code> (PDU wird verworfen, keine Weiterleitung an PduR).</li>\n<li>Fluss geht auf <code>abort</code>: Fehlermeldung an <code>Dem</code> (z. B. <code>SECOC_E_VERIFICATION_FAILURE</code>) bzw. Sicherheits-Event-Logging via <code>IdsM</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>WCET & Task-Scheduling-Einfluss:</strong></li>\n<li>Ist <code>SecOCFreshnessValueSyncAttempts</code> auf $N$ konfiguriert, resultiert dies im Worst Case in $(N + 1)$ sequentiellen CSM-Aufrufen für einen einzigen Rx-Frame.</li>\n<li>Bei synchroner CSM-Verarbeitung im Kontext der Kommunikations-Task (<code>SecOC_MainFunctionRx</code> oder Rx-ISR) führt dies zu massiven CPU-Lastspitzen und potenziellen Task-Overruns. Bei hohen Datenraten oder CAN-Bursts muss die asynchrone CSM-Anbindung mit PDU-Queuing implementiert werden.</li>\n<li><strong>Denial-of-Service (DoS) & Buslast-Exposition:</strong></li>\n<li>Ein Angreifer kann durch bewusst manipulierte MACs die Empfänger-ECU dazu zwingen, für jede injizierte PDU das maximale Synchronisationsfenster vollständig abzuarbeiten. Der Parameter <code>SecOCFreshnessValueSyncAttempts</code> ist daher so klein wie möglich zu wählen (typisch $1 \\dots 3$).</li>\n<li><strong>Zustandskonsistenz der Freshness-Quelle:</strong></li>\n<li>Das Inkrementieren der MSBs (<code>FreshnessVerifyValue ++1</code>) darf während der Iterationen ausschließlich auf einer <strong>lokalen Arbeitskopie</strong> für die Verifikation erfolgen. Eine Übernahme in den persistenten lokalen Freshness-Zustand des Empfängers darf erst und ausschließlich bei Traversierung des <code>continue</code>-Pfades erfolgen.</li>\n</ul>"}, {"id": "FIG-32f5bb42135e016e", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Aktivitätsdiagramm (Activity Diagram) mit expliziten Aktionsknoten (Action Nodes), Entscheidungsknoten (Decision Node), Kontrollflusskanten mit Rückkopplungsschleife und Aktivitätsendknoten (Activity Final Nodes).</li>\n<li><strong>Funktionale Einordnung:</strong> AUTOSAR Classic Platform (ab Release R23-11), BSW Communication Services Layer, Modul <code>SecOC</code> (Secure Onboard Communication).</li>\n<li><strong>Technischer Zweck:</strong> Spezifiziert den normativen Ablauf der MAC- bzw. Signaturverifikation einer empfangenen Secured I-PDU (Rx-Pfad) gemäß <strong>SWS_SecOC_00053</strong>. Bei fehlschlagender Verifikation steuert die Logik eine iterative Wiederholungsschleife unter sukzessiver Ermittlung des nächsten gültigen Freshness-Werts (<code>Next valid Freshness Value</code>), begrenzt durch den Konfigurationsparameter <code>SecOCAuthenticationVerifyAttempts</code>. Dies verallgemeinert das zuvor rein auf MSB-Inkrementierung basierende Resynchronisationsschema für beliebige Freshness-Algorithmen (z. B. FVM).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure & Module:</strong></li>\n<li><code>SecOC</code>: Ausführende BSW-Entität im Communication Services Layer.</li>\n<li><code>Crypto Service Manager (CSM)</code>: Unterlagerte Krypto-Schnittstelle zur kryptografischen Prüfung (<code>Csm_MacVerify</code> bzw. <code>Csm_SignatureVerify</code>).</li>\n<li><code>PduR</code> (PDU Router): Überlagerte Empfangsschicht zur Übergabe erfolgreich verifizierter PDUs (<code>PduR_SecOCRxIndication</code>).</li>\n<li><code>Freshness Management (FVM / SW-C / BswM)</code>: Bereitstellung von Freshness-Werten und Synchronisationsinkrementen.</li>\n<li><strong>Zustands- & Konfigurationsvariablen:</strong></li>\n<li><code>Attempts</code>: Lokale Laufzeitvariable (Zähler der Verifikationsversuche, initial <code>0</code>).</li>\n<li><code>SecOCAuthenticationVerifyAttempts</code> (an der Abbruchkante als <code>SecOCAuthenticationVerifyAttempt</code> beschriftet): ECUC-Konfigurationsparameter für die maximal zulässige Anzahl an Verifikationsiterationen.</li>\n<li><code>Freshness Value</code>: Vollständiger Authentifizierungs- und Frischevektor.</li>\n<li><strong>Kontrollfluss-Knoten & Kanten:</strong></li>\n<li>Startknoten (Initial Node): Eintritt nach PDU-Empfang.</li>\n<li>Aktionsknoten (Action Nodes): <code>MAC verification</code>, <code>Attempts++</code>, <code>Next valid Freshness Value</code>, <code>Drop message</code>.</li>\n<li>Entscheidungsknoten (Decision Node, Raute): Verzweigung anhand von Testergebnis und Guard-Bedingungen.</li>\n<li>Aktivitätsendknoten (Activity Final Nodes, Bullseye): <code>continue</code> (erfolgreiche Verifikation), <code>abort</code> (Abbruch nach Fehlversuchen).</li>\n<li>Kontrollfluss-Rückkopplung: Explizite Kante von <code>Next valid Freshness Value</code> zurück zu <code>MAC verification</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Trigger & Eintritt:</strong> Empfang einer Secured I-PDU via <code>SecOC_RxIndication()</code>. Der Kontrollfluss tritt vom Startknoten unmittelbar in den Aktionsknoten <code>MAC verification</code> ein.</li>\n<li><strong>MAC Verification:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ausführung der Krypto-Prüfung über Nutzdaten (Authentic I-PDU) und den aktuellen Freshness-Wert via CSM.</li>\n<li>Weiterleitung des Kontrollflusses in den Entscheidungsknoten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Verzweigung über Guard-Bedingungen:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Pfad <code>passes</code>:</strong></li>\n<li>Verifikation erfolgreich (MAC/Signatur ist gültig).</li>\n<li>Kontrollfluss terminiert im Endknoten <code>continue</code>.</li>\n<li><code>SecOC</code> aktualisiert den lokalen Freshness-Status und leitet die Authentic I-PDU via <code>PduR_SecOCRxIndication()</code> an den PduR weiter.</li>\n<li><strong>Pfad <code>fails &amp;&amp; [Attempts &lt; SecOCAuthenticationVerifyAttempts]</code>:</strong></li>\n<li>Verifikation ungültig, Limit an Versuchen noch nicht erreicht.</li>\n<li>Aktion 1: <code>Attempts++</code> inkrementiert den Zähler.</li>\n<li>Aktion 2: <code>Next valid Freshness Value</code> ermittelt den nächsten Erwartungswert für die Freshness.</li>\n<li>Rücksprung: Der Kontrollfluss kehrt über die direkte Schleifenkante zur erneuten Ausführung von <code>MAC verification</code> zurück.</li>\n<li><strong>Pfad <code>fails &amp;&amp; [Attempts &gt;= SecOCAuthenticationVerifyAttempt]</code>:</strong></li>\n<li>Verifikation ungültig und maximale Versuchsanzahl erreicht bzw. überschritten.</li>\n<li>Aktion: <code>Drop message</code> verwirft die PDU (optional Meldung an Det/IdsM).</li>\n<li>Kontrollfluss terminiert im Endknoten <code>abort</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Normative Zuordnung:</strong> Spezifikation des Rx-Verifikationsverhaltens gemäß SWS_SecOC_00053 und zugehöriger Anforderungen (SWS_SecOC_00022, SWS_SecOC_00057).</li>\n<li><strong>Generalisierung des Freshness-Managements:</strong> Der Übergang von der festen MSB-Inkrementierung (<code>most significant bits of FreshnessVerifyValue ++1</code>) zur Aktion <code>Next valid Freshness Value</code> entkoppelt die Verifikationsschleife von einer spezifischen Bit-Aufteilung und unterstützt flexible Freshness-Algorithmen (z. B. profilbasierte FVM-Schnittstellen).</li>\n<li><strong>WCET & DoS-Schutz:</strong> Der Konfigurationsparameter <code>SecOCAuthenticationVerifyAttempts</code> begrenzt die worst-case Rechenzeit im BSW-Rx-Pfad. Entwickler müssen den Wert restriktiv konfigurieren, um Denial-of-Service-Angriffe durch absichtlich fehlerhafte Botschaften mit hohem Krypto-Rechenaufwand zu verhindern.</li>\n<li><strong>Asynchroner Modus:</strong> Bei asynchroner CSM-Verifikation muss die Rückkopplungsschleife im Treiber über Callbacks (<code>SecOC_CsmMacVerifyCallbackNotification</code>) reentrant und nicht-blockierend ausgeführt werden.</li>\n<li><strong>Standardkonforme UML-Modellierung:</strong> Die Ersetzung informeller Konnektoren (<code>step back</code>) durch explizite Aktivitätskanten und standardkonforme Endknoten (<code>continue</code>, <code>abort</code>) präzisiert die formale Semantik für Codegeneratoren.</li>\n</ul>"}, {"id": "FIG-a052fcc4375208f4", "releases": ["R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Aktivitätsdiagramm (Activity Diagram) mit expliziten Aktionsknoten (Action Nodes), Entscheidungsknoten (Decision Node), Kontrollflusskanten mit Rückkopplungsschleife und Aktivitätsendknoten (Activity Final Nodes).</li>\n<li><strong>Funktionale Einordnung:</strong> AUTOSAR Classic Platform (ab Release R23-11), BSW Communication Services Layer, Modul <code>SecOC</code> (Secure Onboard Communication).</li>\n<li><strong>Technischer Zweck:</strong> Spezifiziert den normativen Ablauf der MAC- bzw. Signaturverifikation einer empfangenen Secured I-PDU (Rx-Pfad) gemäß <strong>SWS_SecOC_00053</strong>. Bei fehlschlagender Verifikation steuert die Logik eine iterative Wiederholungsschleife unter sukzessiver Ermittlung des nächsten gültigen Freshness-Werts (<code>Next valid Freshness Value</code>), begrenzt durch den Konfigurationsparameter <code>SecOCAuthenticationVerifyAttempts</code>. Dies verallgemeinert das zuvor rein auf MSB-Inkrementierung basierende Resynchronisationsschema für beliebige Freshness-Algorithmen (z. B. FVM).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure & Module:</strong></li>\n<li><code>SecOC</code>: Ausführende BSW-Entität im Communication Services Layer.</li>\n<li><code>Crypto Service Manager (CSM)</code>: Unterlagerte Krypto-Schnittstelle zur kryptografischen Prüfung (<code>Csm_MacVerify</code> bzw. <code>Csm_SignatureVerify</code>).</li>\n<li><code>PduR</code> (PDU Router): Überlagerte Empfangsschicht zur Übergabe erfolgreich verifizierter PDUs (<code>PduR_SecOCRxIndication</code>).</li>\n<li><code>Freshness Management (FVM / SW-C / BswM)</code>: Bereitstellung von Freshness-Werten und Synchronisationsinkrementen.</li>\n<li><strong>Zustands- & Konfigurationsvariablen:</strong></li>\n<li><code>Attempts</code>: Lokale Laufzeitvariable (Zähler der Verifikationsversuche, initial <code>0</code>).</li>\n<li><code>SecOCAuthenticationVerifyAttempts</code> (an der Abbruchkante als <code>SecOCAuthenticationVerifyAttempt</code> beschriftet): ECUC-Konfigurationsparameter für die maximal zulässige Anzahl an Verifikationsiterationen.</li>\n<li><code>Freshness Value</code>: Vollständiger Authentifizierungs- und Frischevektor.</li>\n<li><strong>Kontrollfluss-Knoten & Kanten:</strong></li>\n<li>Startknoten (Initial Node): Eintritt nach PDU-Empfang.</li>\n<li>Aktionsknoten (Action Nodes): <code>MAC verification</code>, <code>Attempts++</code>, <code>Next valid Freshness Value</code>, <code>Drop message</code>.</li>\n<li>Entscheidungsknoten (Decision Node, Raute): Verzweigung anhand von Testergebnis und Guard-Bedingungen.</li>\n<li>Aktivitätsendknoten (Activity Final Nodes, Bullseye): <code>continue</code> (erfolgreiche Verifikation), <code>abort</code> (Abbruch nach Fehlversuchen).</li>\n<li>Kontrollfluss-Rückkopplung: Explizite Kante von <code>Next valid Freshness Value</code> zurück zu <code>MAC verification</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Trigger & Eintritt:</strong> Empfang einer Secured I-PDU via <code>SecOC_RxIndication()</code>. Der Kontrollfluss tritt vom Startknoten unmittelbar in den Aktionsknoten <code>MAC verification</code> ein.</li>\n<li><strong>MAC Verification:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ausführung der Krypto-Prüfung über Nutzdaten (Authentic I-PDU) und den aktuellen Freshness-Wert via CSM.</li>\n<li>Weiterleitung des Kontrollflusses in den Entscheidungsknoten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Verzweigung über Guard-Bedingungen:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Pfad <code>passes</code>:</strong></li>\n<li>Verifikation erfolgreich (MAC/Signatur ist gültig).</li>\n<li>Kontrollfluss terminiert im Endknoten <code>continue</code>.</li>\n<li><code>SecOC</code> aktualisiert den lokalen Freshness-Status und leitet die Authentic I-PDU via <code>PduR_SecOCRxIndication()</code> an den PduR weiter.</li>\n<li><strong>Pfad <code>fails &amp;&amp; [Attempts &lt; SecOCAuthenticationVerifyAttempts]</code>:</strong></li>\n<li>Verifikation ungültig, Limit an Versuchen noch nicht erreicht.</li>\n<li>Aktion 1: <code>Attempts++</code> inkrementiert den Zähler.</li>\n<li>Aktion 2: <code>Next valid Freshness Value</code> ermittelt den nächsten Erwartungswert für die Freshness.</li>\n<li>Rücksprung: Der Kontrollfluss kehrt über die direkte Schleifenkante zur erneuten Ausführung von <code>MAC verification</code> zurück.</li>\n<li><strong>Pfad <code>fails &amp;&amp; [Attempts &gt;= SecOCAuthenticationVerifyAttempt]</code>:</strong></li>\n<li>Verifikation ungültig und maximale Versuchsanzahl erreicht bzw. überschritten.</li>\n<li>Aktion: <code>Drop message</code> verwirft die PDU (optional Meldung an Det/IdsM).</li>\n<li>Kontrollfluss terminiert im Endknoten <code>abort</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Normative Zuordnung:</strong> Spezifikation des Rx-Verifikationsverhaltens gemäß SWS_SecOC_00053 und zugehöriger Anforderungen (SWS_SecOC_00022, SWS_SecOC_00057).</li>\n<li><strong>Generalisierung des Freshness-Managements:</strong> Der Übergang von der festen MSB-Inkrementierung (<code>most significant bits of FreshnessVerifyValue ++1</code>) zur Aktion <code>Next valid Freshness Value</code> entkoppelt die Verifikationsschleife von einer spezifischen Bit-Aufteilung und unterstützt flexible Freshness-Algorithmen (z. B. profilbasierte FVM-Schnittstellen).</li>\n<li><strong>WCET & DoS-Schutz:</strong> Der Konfigurationsparameter <code>SecOCAuthenticationVerifyAttempts</code> begrenzt die worst-case Rechenzeit im BSW-Rx-Pfad. Entwickler müssen den Wert restriktiv konfigurieren, um Denial-of-Service-Angriffe durch absichtlich fehlerhafte Botschaften mit hohem Krypto-Rechenaufwand zu verhindern.</li>\n<li><strong>Asynchroner Modus:</strong> Bei asynchroner CSM-Verifikation muss die Rückkopplungsschleife im Treiber über Callbacks (<code>SecOC_CsmMacVerifyCallbackNotification</code>) reentrant und nicht-blockierend ausgeführt werden.</li>\n<li><strong>Standardkonforme UML-Modellierung:</strong> Die Ersetzung informeller Konnektoren (<code>step back</code>) durch explizite Aktivitätskanten und standardkonforme Endknoten (<code>continue</code>, <code>abort</code>) präzisiert die formale Semantik für Codegeneratoren.</li>\n</ul>"}], "trans": [{"from": "FIG-c9353920c306bf20", "to": "FIG-0d5a4627ecec958a", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-0d5a4627ecec958a", "to": "FIG-117b8a2918abfa19", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-117b8a2918abfa19", "to": "FIG-23addafec55e3345", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-23addafec55e3345", "to": "FIG-32f5bb42135e016e", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Aktionsknoten <code>MAC verification</code>: Neu eingeführt als expliziter Aktionsknoten vor dem Entscheidungsknoten; ersetzt die frühere bloße Beschriftung der Eingangskante.</li>\n<li>Guard-Bedingungen / Konfigurationsparameter: Ersetzung des Parameters <code>SecOCFreshnessValueSyncAttempts</code> durch <code>SecOCAuthenticationVerifyAttempts</code> (Wiederholungszweig) bzw. <code>SecOCAuthenticationVerifyAttempt</code> (Abbruchzweig).</li>\n<li>Berechnungslogik der Freshness: Ersetzung der spezifischen Aktion <code>most significant bits of FreshnessVerifyValue ++1</code> durch die verallgemeinerte Aktion <code>Next valid Freshness Value</code>.</li>\n<li>Kontrollfluss der Wiederholungsschleife: Wegfall des Sprung-Konnektors <code>step back</code>; stattdessen führt eine explizite Rückkopplungskante von <code>Next valid Freshness Value</code> direkt zurück in die Aktion <code>MAC verification</code>.</li>\n<li>Endknoten: Ersetzung der benutzerdefinierten farbigen Konnektoren (<code>continue</code>, <code>abort</code>) durch standardkonforme UML-Aktivitätsendknoten (Bullseye).</li>\n<li>Notationsstil: Vollständige Umstellung auf standardkonforme UML-Aktivitätsdiagramm-Syntax mit einheitlichen Aktionsknoten (abgerundete Rechtecke).</li>\n</ul>"}, {"from": "FIG-32f5bb42135e016e", "to": "FIG-a052fcc4375208f4", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
